import { assertSupported } from './claimGuard.js'
import type { CatalogFinding } from './findings.js'

// PHASE 6 — the business-value layer.
//
// BUSINESS SOURCE: Team Answer Sections F.3/F.4 and the Phase 6 brief, which
// asks for each finding to be readable as a business conversation rather than
// a defect list:
//
//   OBSERVATION -> BUSINESS PAIN -> WHY IT MATTERS -> POTENTIAL OPPORTUNITY
//   -> RECOMMENDED DIRECTION
//
// Two constraints shape every line below.
//
// FIRST: nothing here is generated by a model. Each finding CODE maps to a
// written interpretation, chosen once and reviewed once. A model asked to
// write the business pain for a finding would write something plausible and
// occasionally something indefensible, and the whole point of this engine is
// that a salesperson can put the output in front of a prospect without
// reading it first. Deterministic mapping is also the only version that can
// be tested.
//
// SECOND: the causal chain stops where the evidence stops. Better product
// data makes products easier to find and compare. Whether that earns the
// customer money is not something a page sample can establish, so this file
// says "potential opportunity" and marks financial analysis as not quantified.
// The claim guard enforces it; the language here is written so the guard
// never has to fire.

export interface BusinessPain {
  findingCode: string
  /** What was seen, in the finding's own sample-scoped terms. */
  observation: string
  /** What that may cost the buyer's customer, stated as a possibility. */
  businessPain: string
  whyItMatters: string
  potentialOpportunity: string
  recommendedDirection: string
}

export interface BusinessValue {
  whatWeObserved: string
  whyThisMatters: string
  whereThePainMayAppear: string
  howAltiusNxtCanHelp: string
  improvedExperience: string
  nextStep: string
  /** Required by the brief: financial impact is never implied. */
  financialNote: string
}

export const DISCOVERABILITY_LENSES = ['seo', 'aeo', 'geo'] as const
export type DiscoverabilityLens = (typeof DISCOVERABILITY_LENSES)[number]

export interface DiscoverabilityNote {
  lens: DiscoverabilityLens
  /** The finding this was read off. Never free-standing. */
  findingCode: string
  observation: string
  consideration: string
}

// ── Pain interpretations, one per finding ──────────────────────────────────
