/**
 * Turns one finding into the five-part business reading.
 *
 * The observation is the finding's OWN sample-scoped metric — copied, not
 * rewritten — so the number a customer reads is the number the audit
 * defended. Only the interpretation around it is written here.
 */
export function buildBusinessPain(finding: CatalogFinding): BusinessPain {
  const t = BY_CODE[finding.code] ?? BY_CATEGORY[finding.category] ?? {
    businessPain: `${finding.title} was observed on the inspected pages.`,
    whyItMatters: finding.impact,
    potentialOpportunity: 'Addressing it would make the affected product data usable for filtering and comparison.',
    recommendedDirection: finding.recommendation,
  }

  // Most finding texts already carry their own denominator — "could not be
  // found on 9 of the 12 inspected product pages". Appending the metric to
  // those produced "...on 12 of the 12 inspected product pages. (0 of 12
  // inspected product pages)", which reads as a contradiction because the two
  // numbers count opposite things. So the count is only added where the
  // sentence does not already state one.
  const statesItsOwnCount = /\b\d+\s+of\s+(?:the\s+)?\d+\b/.test(finding.finding)
  const observation = statesItsOwnCount
    ? finding.finding.trim().replace(/\.?$/, '.')
    : `${finding.finding.trim().replace(/\.?$/, '')} (${finding.observedCount} of ${finding.sampleSize} inspected ${finding.sampleUnit}).`

  return {
    findingCode: finding.code,
    observation: assertSupported(`pain.${finding.code}.observation`, observation),
    businessPain: assertSupported(`pain.${finding.code}.businessPain`, t.businessPain),
    whyItMatters: assertSupported(`pain.${finding.code}.whyItMatters`, t.whyItMatters),
    potentialOpportunity: assertSupported(`pain.${finding.code}.potentialOpportunity`, t.potentialOpportunity),
    recommendedDirection: assertSupported(`pain.${finding.code}.recommendedDirection`, t.recommendedDirection),
  }
}

// ── Discoverability: SEO / AEO / GEO ───────────────────────────────────────
//
// The brief permits observations about factors that MAY influence
// discoverability and forbids any claim about actual ranking. So each note
// below is anchored to a finding that was actually recorded, and phrased as a
// consideration rather than a diagnosis. There is no note that exists on its
// own — if the audit did not record the finding, the note does not appear.

const DISCOVERABILITY: Record<string, Array<{ lens: DiscoverabilityLens; consideration: string }>> = {
  no_product_structured_data: [
    {
      lens: 'seo',
      consideration:
        'Search engines read product markup to understand what a page describes. Without it, a product page is interpreted as ordinary text — a potential discoverability consideration, not a measured ranking effect.',
    },
    {
      lens: 'aeo',
      consideration:
        'Assistants answering a product question draw on structured data where it exists. Its absence means any answer has to be inferred from prose.',
    },
    {
      lens: 'geo',
      consideration:
        'Systems that summarise products for a generated answer rely on machine-readable attributes. Unstructured pages give them less to work with.',
    },
  ],
  weak_product_description: [
    {
      lens: 'seo',
      consideration:
        'Where similar products carry similar text, there is little to distinguish the pages from one another. This is a potential discoverability consideration observed on the inspected pages.',
    },
    {
      lens: 'aeo',
      consideration:
        'A question-answering system needs distinguishing detail to match a product to a question. Thin descriptions offer little to match on.',
    },
  ],
  incomplete_specifications: [
    {
      lens: 'aeo',
      consideration:
        'Specification questions are answered from named attributes. Where specifications sit only in prose, they are harder for any system to extract reliably.',
    },
  ],
  incomplete_product_metadata: [
    {
      lens: 'seo',
      consideration:
        'Page metadata determines how a page is represented in a result list. Incomplete metadata was observed on the inspected pages.',
    },
  ],
  duplicate_pages: [
    {
      lens: 'seo',
      consideration:
        'Where one product is reachable at several addresses, it is ambiguous which is the primary page. A canonical declaration resolves that ambiguity.',
    },
  ],
  broken_internal_links: [
    {
      lens: 'seo',
      consideration:
        'Unresolved internal links interrupt the paths through a catalogue that both buyers and crawlers follow.',
    },
  ],
  soft_404_pages: [
    {
      lens: 'seo',
      consideration:
        'Pages returning a success status with no product content are treated as real pages by systems reading the site.',
    },
  ],
}

/** Discoverability notes for the findings this audit actually recorded. */
export function buildDiscoverabilityNotes(findings: CatalogFinding[]): DiscoverabilityNote[] {
  const notes: DiscoverabilityNote[] = []
  for (const f of findings) {
    for (const entry of DISCOVERABILITY[f.code] ?? []) {
      notes.push({
        lens: entry.lens,
        findingCode: f.code,
        observation: `${f.title}: ${f.observedCount} of ${f.sampleSize} inspected ${f.sampleUnit}.`,
        consideration: assertSupported(`discoverability.${f.code}.${entry.lens}`, entry.consideration),
      })
    }
  }
  return notes
}

// ── The case-study layer ───────────────────────────────────────────────────

export interface BusinessValueInput {
  companyName: string
  findings: CatalogFinding[]
  pains: BusinessPain[]
  productPagesInspected: number
  pagesInspected: number
  hasWorkbenchDemo: boolean
}

/**
 * The six-section business reading of the whole audit.
 *
 * Written to be read aloud in a sales conversation. It names the company, uses
 * its actual numbers, and stops at the point where the evidence stops — which
 * is why the financial note exists as a separate, explicit sentence rather
 * than as a hedge buried in a paragraph.
 */
export function buildBusinessValue(input: BusinessValueInput): BusinessValue {
  const { companyName, findings, pains, productPagesInspected, pagesInspected } = input
  const top = pains.slice(0, 3)
  const high = findings.filter((f) => f.priority === 'high')

  const whatWeObserved = findings.length
    ? `We inspected ${pagesInspected} page(s) on the ${companyName} website, ${productPagesInspected} of them product pages, and recorded ${findings.length} product-data finding(s). ${
        high.length ? `${high.length} of them affect fields a buyer needs in order to find and filter a product.` : 'None of them affect the fields a buyer needs in order to find and filter a product.'
      }`
    : `We inspected ${pagesInspected} page(s) on the ${companyName} website, ${productPagesInspected} of them product pages, and recorded no product-data finding against them.`

  const whyThisMatters = top.length
    ? top.map((p) => p.whyItMatters).join(' ')
    : 'Product data on the inspected pages carried the fields a buyer needs. That is the position worth protecting as the catalogue grows.'

  const whereThePainMayAppear = top.length
    ? top.map((p) => p.businessPain).join(' ')
    : 'No pain was evident on the pages inspected.'

  const howAltiusNxtCanHelp = findings.length
    ? 'AltiusNXT works on the product record itself: agreeing the attribute set for each product family, populating it from the sources that already hold the values, and publishing it in a form both buyers and systems can read. The audit points at where to start.'
    : 'AltiusNXT can review a wider sample and confirm whether the position holds across the catalogue.'

  const improvedExperience = input.hasWorkbenchDemo
    ? `A worked example from one of the ${companyName} product pages is available, showing the same product as it appears today alongside the same product with its attributes structured. Every improved value traces back to something already on the page.`
    : findings.length
      ? 'The improved position is a product page where the specifications, identifiers and availability a buyer needs are each present as named values — filterable, comparable, and readable by the systems that list them elsewhere.'
      : 'The current position already carries the fields a buyer needs on the pages inspected.'

  const nextStep =
    'A 15-minute walkthrough covers what was found, what it would take to address, and what a worked example looks like on your own products.'

  const financialNote =
    'Potential opportunity — not quantified in this audit. This review observed product data on a bounded sample of pages. It did not measure sales, traffic or cost, and nothing here should be read as a projection of any of them.'

  return {
    whatWeObserved: assertSupported('value.whatWeObserved', whatWeObserved),
    whyThisMatters: assertSupported('value.whyThisMatters', whyThisMatters),
    whereThePainMayAppear: assertSupported('value.whereThePainMayAppear', whereThePainMayAppear),
    howAltiusNxtCanHelp: assertSupported('value.howAltiusNxtCanHelp', howAltiusNxtCanHelp),
    improvedExperience: assertSupported('value.improvedExperience', improvedExperience),
    nextStep: assertSupported('value.nextStep', nextStep),
    financialNote: assertSupported('value.financialNote', financialNote),
  }
}
